#!/usr/bin/env python3
"""The overlay's second font: a subset of DejaVu Sans Mono as a C array.

    python3 third_party/dejavu/make_subset.py <DejaVuSansMono.ttf>

writes src/overlay/overlay_font_ext.h. The source is the file of that name in
dejavu-fonts-ttf-2.37.tar.bz2 (https://github.com/dejavu-fonts/dejavu-fonts,
release version_2_37; sha256 of the .ttf below). Needs fontTools.

The overlay's first font is Dear ImGui's own (ProggyForever, Basic Latin and
Latin-1). This one is merged behind it for what that lacks:

    U+0100-024F   Latin Extended-A and -B (Central European, Baltic, Turkish,
                  Romanian, Croatian ... letters)
    U+0370-03FF   Greek
    U+0400-04FF   Cyrillic
    U+2010-2027   dashes, typographic quotes, the ellipsis, and a few signs
    U+25A1        the white square shown for a character neither font has

Only outlines and the character map are kept: no hinting, no layout tables,
no names (a modified copy must not carry the Bitstream Vera name; it carries
none).
"""
import hashlib
import io
import os
import sys

from fontTools import subset
from fontTools.ttLib import TTFont

SHA256 = "b4a6c3e4faab8773f4ff761d56451646409f29abedd68f05d38c2df667d3c582"
UNICODES = "U+0100-024F,U+0370-03FF,U+0400-04FF,U+2010-2027,U+2030,U+2039,U+203A,U+2122,U+25A1"


def main():
    src = sys.argv[1]
    data = open(src, "rb").read()
    digest = hashlib.sha256(data).hexdigest()
    if digest != SHA256:
        sys.exit("not the DejaVuSansMono.ttf of release 2.37 (sha256 %s)" % digest)
    opts = subset.Options()
    opts.hinting = False
    opts.desubroutinize = True
    opts.layout_features = []
    opts.name_IDs = []
    opts.notdef_outline = True
    opts.drop_tables += ["FFTM", "GDEF", "GPOS", "GSUB"]
    font = TTFont(io.BytesIO(data))
    sub = subset.Subsetter(opts)
    sub.populate(unicodes=subset.parse_unicodes(UNICODES))
    sub.subset(font)
    out = io.BytesIO()
    font.save(out)
    ttf = out.getvalue()
    here = os.path.dirname(os.path.abspath(__file__))
    dest = os.path.join(here, "..", "..", "src", "overlay", "overlay_font_ext.h")
    with open(dest, "w", newline="\n") as f:
        f.write("/* Generated by third_party/dejavu/make_subset.py: a subset of DejaVu Sans Mono\n"
                " * 2.37 (%d characters, %d bytes). Fonts (c) 2003 Bitstream, Inc.; DejaVu\n"
                " * changes are in the public domain; glyphs from Arev (c) 2006 Tavmjong Bah.\n"
                " * The licence is third_party/dejavu/LICENSE.txt. Do not edit. */\n"
                % (len(font.getBestCmap()), len(ttf)))
        f.write("static const unsigned char k_overlay_font_ext[%d] = {\n" % len(ttf))
        for i in range(0, len(ttf), 20):
            f.write("    " + ",".join(str(b) for b in ttf[i:i + 20]) + ",\n")
        f.write("};\n")
    print("%s: %d characters, %d bytes" % (os.path.normpath(dest), len(font.getBestCmap()), len(ttf)))


if __name__ == "__main__":
    main()
